import { STAFF_MATCHES_PER_SEASON } from '@/lib/clubManagerStaff';
import { BOARD_FRESH, KITTY_TOP_SHARE } from '@/lib/clubManagerBoardVerdict';
import { CM_VAR_LIVE } from '@/lib/clubManagerVarLive';
import { REAL_LEAGUES } from '@/lib/clubManager';
import { REAL_LEAGUE_FIXTURES, realFixtureListAsOfText } from '@/lib/clubManagerFixtures';
import { CM_VAR_COVERED_NAMES, CM_VAR_REAL, CM_VAR_KINDS } from '@/data/clubManagerVarRates';

/* Round 1303 (the lead's decision 2): the kinds of review the game plays are data (CM_VAR_KINDS, generated from
   the rates ledger), and the VAR block below says only what those kinds do. With the goal kind alone it says
   goals only and never mentions a penalty a review gives. It never states a real league's rate (decision 1):
   the one number it prints is the game's own, how often the game rules a goal out. */
const VAR_GOALS = (CM_VAR_KINDS as readonly string[]).includes('goal');
const VAR_PENALTIES = (CM_VAR_KINDS as readonly string[]).includes('penalty');

/* Round 1225: the leagues with a real first season fixture list, read off the registry, so this
   paragraph cannot name a league the game does not bind or leave one out. Grouped by what the
   order of each list is the order of, in the registry's own words. No link here: the Calendar
   names the sources of the league a career is in. scripts/simCmLeagueFixtures.mjs section J holds it. */
function realFixtureGroups(): { asOf: string; leagues: { id: string; name: string }[] }[] {
  const groups: { asOf: string; leagues: { id: string; name: string }[] }[] = [];
  for (const entry of REAL_LEAGUE_FIXTURES) {
    const asOf = realFixtureListAsOfText(entry.asOf);
    let group = groups.find(g => g.asOf === asOf);
    if (!group) { group = { asOf, leagues: [] }; groups.push(group); }
    group.leagues.push({ id: entry.leagueId, name: REAL_LEAGUES.find(l => l.id === entry.leagueId)?.name ?? entry.leagueId });
  }
  return groups;
}

export default function ClubManagerHelp() {
  return (
<div className="space-y-3 text-left">
              <p data-cm-help="real-fixtures">📋 <span className="font-semibold text-foreground">Real first-season fixtures in {REAL_LEAGUE_FIXTURES.length} {REAL_LEAGUE_FIXTURES.length === 1 ? 'league' : 'leagues'}.</span> A new 2026/27 career in one of these leagues, in the unedited modern world, uses the real opponent order and home/away venues:{' '}{realFixtureGroups().map((group, g, all) => <span key={group.asOf}>{group.leagues.map((league, i) => <span key={league.id}>{i === 0 ? '' : i === group.leagues.length - 1 ? ' and ' : ', '}<span data-cm-fixture-league={league.id}>{league.name}</span></span>)} (<span data-cm-fixture-asof={group.leagues.map(l => l.id).join(' ')}>{group.asOf}</span>){g === all.length - 1 ? '. ' : '; '}</span>)}A match moved after that is not followed. Calendar dates, kick off times and every match result are simulated. Example: Everton start at home to Crystal Palace, then visit Bournemouth. Take a club over part way through that first season and the weeks before you were played in the real order too. Other leagues, custom clubs, edited worlds, older saves, later seasons, a job you carry on from Manager Hot Seat and a club you move to during a season keep generated fixtures. Your Calendar names the two sources for your league.</p>
              <p>🌍 <span className="font-semibold text-foreground">Pick any club in 27 real leagues.</span> The big five (2026-27 lineups with promotions and relegations applied), the EFL Championship, the 2. Bundesliga, Serie B, Ligue 2 and the Segunda División (20 of its real 22 clubs), the Primeira Liga, the Scottish Premiership, the Süper Lig, the Belgian Pro League, the Austrian Bundesliga, the Super League Greece, the Danish Superliga, the Swiss Super League, Croatia's SuperSport HNL, the Saudi Pro League, both MLS conferences, Brazil's Serie A, Liga MX, the Eredivisie, the A-League Men and the Russian Premier League: 454 clubs and over 5,000 real players at their real market values (August 2026, after the summer window; the A-League squads were read in October, the Russian squads were read in October too, every player on at least two sites, and the Serie B, Ligue 2 and Segunda squads are last season's players their clubs still list, with no summer signings yet). Where the data runs thin a squad is topped up with made up youth players, marked as made up. Giants get huge budgets and zero patience; underdogs get small budgets and a low bar.</p>
              <p>📅 <span className="font-semibold text-foreground">Pick when you start.</span> 2026-27 is today's game: real clubs, real players, real market values, with the summer window applied and thin squads topped up with marked youth. Or go back: 2020-21 is Haaland and Bellingham at Dortmund, Mbappé and Neymar at PSG and Bruno Fernandes at United, with that summer's big moves already made, Havertz and Werner at Chelsea, Thiago at Liverpool and Suárez at Atlético; 2015-16 is the season Leicester won at 5000 to 1, with Vardy, Mahrez and Kante at their real pre-title values, MSN at Barcelona, De Bruyne newly at City and, since the Serie A joined the era, Juventus chasing a fifth straight Scudetto with Dybala newly arrived from Palermo, and now the Bundesliga and Ligue 1 too, with Lewandowski and Douglas Costa at Bayern, Aubameyang and Reus at Dortmund, and Ibrahimovic and Di Maria at PSG; 2010-11 is prime Messi, Mourinho's Madrid and Rooney's United, and now the rest of the big five too: Klopp's young Dortmund, Ibrahimovic's Milan and Lille's double; 2005-06 is Ronaldinho's Ballon d'Or Barcelona with a 17 year old Messi on the bench, Mourinho's back to back Chelsea, Henry's Arsenal and Gerrard's Istanbul champions, back when the second European prize was still called the UEFA Cup, and the boards say so, and now with the rest of the big five around them: the Juventus of Buffon, Cannavaro, Nedved and Ibrahimovic, Shevchenko's Milan, Ballack's Bayern and Juninho's Lyon. Each past season is the real top flight football of its year: all four run the whole big five, the Premier League, La Liga, Serie A, the Bundesliga and Ligue 1, all 98 clubs each, hundreds of real players at their real ages and values from that year, with the famous summer moves applied. The older eras' giants rate like the legends they are, above anyone in the current generation, with the whole era scaled around them; money in 2020-21 was close to today's, so its stars rate about where they would now. Every era is a sealed world, so no 2026 player can leak into your past market, and there is no Conference League back there because it did not exist yet. We only offer a past we hold real data for, and we never invent one: 2005-06 is the floor of the records, so there is no 2000 era. As your save runs deep, players age, retire and get replaced; anyone the game makes up is marked MADE UP wherever he appears, so you always know who is real.</p>
              <p>✨ <span className="font-semibold text-foreground">Or create your own club.</span> Any league, either era: name it, build the crest (shape, pattern, your colors, your initials), name your stadium, and choose your backing. Your club takes the league place of the division's weakest side and starts with 24 generated players, all marked as made up, as good as you like. Your backing sets your wage room: the ceiling a real club with that budget gets. Start with a better squad than that money could buy and it plays exactly that well, brings the extra wage room its wages need, and that extra room goes as those players leave. They sell on at the prices the money's own squad would fetch, and still go up in step as they improve, wherever they go and even if you sign one back. At or under what the money buys, they sell for what they are worth. Every real player stays real, and the market is where you sign them. The board reads your squad, not your wallet: big money in a smaller league gets told to win it, the same money in the Premier League gets told to survive first. Created clubs can go up or down in modern leagues with a second division. Example: win the Championship, then start next season to play in the Premier League. Past eras keep their original division.</p>
              <p>🌍 <span className="font-semibold text-foreground">Or move the clubs around first.</span> In today's world, the World editor tile on the nation step lets you move any club to any league before you start. Every move is a swap, so each league keeps its real size, fixtures and places. Example: swap Celtic with Brentford. Celtic now play a full Premier League season and the FA Cup, Brentford play in Scotland, and the boards judge both against their new leagues: Brentford are asked to win the Scottish Premiership, Celtic to stay up. Europe in your first season goes to the clubs who really qualified last season, wherever they play now; after that your edited tables decide it, and the edited leagues promote and relegate like any other. Reset puts the real world back. A club you create yourself always starts in the real world.</p>
              <p>🧑‍💼 <span className="font-semibold text-foreground">Build your manager, or skip it.</span> Before kickoff you can name him, give him a face (skin, hair, beard, touchline outfit, kit colour and age, all drawn shapes, never a real person), and pick his homeland from any nation in the game's international football (all six confederations), his background and his style. The background is worth one skill point in its own tree on day one: Ex player puts it in Man Management, Career coach in Tactics, Analyst in Recruitment, Youth coach in Youth, Ex agent in Negotiation, Boardroom in Finance and TV pundit in Media. It works exactly like a point bought with XP and costs you none. The style sets your day one formation and mentality, eleven of them to pick from. Worked example: a Boardroom manager from Ghana who likes Catenaccio kicks off in a 5-4-1 on Defensive with Finance at 1 (about 2 percent more money a head at every home gate), and if he wins enough it is Ghana who call. Change his name, homeland or face any time from Edit on the Manager panel (a real player's name is refused there too); the background stays. Skipped it at kickoff? Name your manager from the same panel and his point lands then.</p>
              <p>👟 <span className="font-semibold text-foreground">Players age and they stop playing.</span> A thirty year old slips a point a season, a thirty five year old slips three or four, and how fast depends on where he plays: keepers last for years, wingers and full backs go first. Somewhere around thirty four to thirty seven most of them retire for good. Sign the young ones early, get your kids in, or your best XI will quietly rot underneath you.</p>
              <p>📋 <span className="font-semibold text-foreground">The board names the actual prize</span>: win the league, qualify for the Champions League or Europa League, reach the top half, or stay up, plus a cup target, a rival to finish above, and squad mandates. Hit them and your stock rises; miss them and the confidence meter drains.</p>
              <p>🛒 <span className="font-semibold text-foreground">And two of them are things you go and buy.</span> On top of the season demands, every board makes two specific asks a year, drawn from five shapes and worked out from your club and your era rather than written down: get one more player from your own country into the squad, keep one more aged 30 or over, sign somebody in the thinnest line of your squad, sign somebody 21 or under at a rating the market says you can reach, or spend a set fee or more on one signing. Every threshold is read off the market you actually have and the money you actually hold, so a big club today gets told to spend nine figures and a modest one in 2005 gets told to spend a few million, and the two asks together never cost more than the pot. That rating floor on the young one is where this game keeps headroom: a signing of 21 or under can still add up to ten rating points, and about one in twelve is carrying a lot more than that. The board screen shows the two under In the market, with the line that says how each one is graded.</p>
              <p>📩 <span className="font-semibold text-foreground">The inbox is not just your players any more.</span> The board chase an ask you have not met, and you can take their money (a quarter of the kitty, and a point off their patience), give them your word (marked on the board screen, and worth three points of next season's opening confidence either way) or tell them no, which drops the ask and costs three points now. An agent writes about a client of his in your squad with a year left, priced at the contracts desk's own terms, and signing him takes his sale value back off the floor that a last year on a deal puts it on. Your assistant argues about the training plan, but only when the plan really is wrong for the squad in front of him. The supporters trust write about the ticket price when it is on premium. A reporter wants a line on whether the squad is good enough, and backing them lifts every player's morale and the press mood. Every one of those moves a number with a screen behind it, so what you decided in October is still readable in April.</p>
              <p>⚖️ <span className="font-semibold text-foreground">Appeal a red card, and make the calls on the decisions desk.</span> After a straight red the club secretary puts an appeal on the desk at the top of your inbox, with the odds in plain numbers: 40% on a man's first red of the season, 25% on his second, 15% after that. Win and the ban is wiped, lose and the panel adds a match, or just accept it. A second yellow can't be appealed. Between matches a situation lands now and then (a sponsor shoot, an investors dinner, a quiet word with a player whose head has dropped), and every answer names the one number it moves: board patience, press mood, his morale or the transfer budget. There is always an answer that changes nothing. Anything still open when the next match kicks off closes with nothing changed, so answer first. Example: your striker sees his first straight red of the season and gets 2 matches. Appeal, and 40 times in 100 he plays next week; the other 60 he sits out 3.</p>
              <p>🗓️ <span className="font-semibold text-foreground">Play a full season in your club's REAL league</span>, at its real length, against its real clubs, plus the domestic cup and the Champions League if you qualify, while every other league in the world plays out alongside yours. In the Champions League you can watch all eight groups, and a projected knockout bracket tracks the leaders until the real draw locks in after matchday 6. Not in it? You can still follow the whole thing from Cups (see the Champions League block below).</p>
              <p>📆 <span className="font-semibold text-foreground">The calendar is the season laid out month by month, and you can tap any day and sim to it.</span> Match days name the opponent, home or away, with the competition, and wear a result once played. The summer window is open from kickoff and the January window opens in January, on the first Saturday of the new year in most leagues and a little later in one long enough to reach January on its own; each one closes at the final whistle of its deadline day, marked with a padlock, after four of your matches in the summer and three in January. 2020-21 is the exception: that season really kicked off late (September in most of the big five, late August in France), so its calendar starts when it really did, up to three league rounds go midweek to fit it in, and its summer window stays open until your last match before the real deadline of 5 October, however many matches that is. Tap a day, read what it holds, and hit Sim to play everything up to it in one go: a match day plays that match, a quiet day plays everything before it and stops. The four fast forwards (next match, about a month, to the window, rest of season) are the same tap on a chosen day. Every run stops early for the things that need you: a window opening, the season review, the sack, or a club's approach landing.</p>
              <p>🌍 <span className="font-semibold text-foreground">International breaks take your players away.</span> From 2026-27 on the national teams call up their best three times a season: late September into October, November and March. The autumn and November windows of 2026-27 are on the real calendar's dates. Every other window follows the same pattern and the calendar marks its dates as approximate, and the seasons before 2026-27, the older eras included, use the four window pattern football had just before that (September, October, November, March) as a stand in. A man goes when the game knows his country and he rates among that country's best in your world. Made up players never go, and an injured man stays home. Your fixtures do not stop for a window here, so they go straight after your last game before it and come back for your next one tired: a man who started his country's games loses more legs than one who sat on their bench, a trip to another continent costs more, the long autumn window with four games costs most, and now and then somebody comes back with a knock. Your assistant names who went in the inbox and asks whether to rest the spent ones for that one game. Worked example: Arsenal, November. Ten of your starters go. Your Brazilian winger starts both games for Brazil and is back at 50 fitness, your English full back sits on England's bench and is back at 74. Pick them anyway and your best eleven plays on tired legs. Rest the spent ones and your assistant sits the winger out, a fresher man plays, and the winger is back near full for the game after, while the full back starts because his legs are fine. A rest lasts one match: your tactics screen shows who plays instead, the rested men sit on your bench (put one back in your eleven and he plays), and after the game they go back into the side. When nobody on the bench beats tired legs your assistant says so and starts them. The calendar marks each window with 🌍 on the day it opens, and the squad list tags who is BACK and who is RESTING.</p>
              <p>🧠 <span className="font-semibold text-foreground">Set tactics before each match:</span> formation, mentality and your starting XI. Form, morale, fatigue, injuries and home advantage all matter. Seventeen shapes now, grouped by the back line (three, four or five), and switching one carries every man across by his slot before the auto pick fills whatever is left. Anyone can play anywhere, ten defenders if you like, but the match reads each man in his slot: a position he holds costs nothing, a neighbouring one (a winger on the other flank, a full back at wing back, a number ten dropped into the holding spot) takes 2 rating points off him, the wrong line takes 6, and a keeper outfield or an outfielder in goal takes 14, so the average in the header is the fit adjusted one and every token wears its ring, amber for a neighbouring spot and red for the rest. The bench sits under the pitch, same position first for whichever spot you tapped, the men who cannot play greyed with the reason, and a tap on a bench man then a spot puts him there (or a spot then a bench man, or drag). Every slot carries a duty (sweeper keeper or shot stopper, stopper or cover, attacking or holding full back, anchor or deep playmaker, box to box or playmaker, creator or shadow striker, winger or inside forward, poacher, target man or false nine): a small nudge to how you attack and defend, the whole eleven's worth capped well under one mentality step, plus a say in who gets on the end of things, so a poacher takes more of your goals and a target man lays more on. The set piece card names the captain, the corner takers left and right, the free kick taker and the penalty taker, with an auto pick if you would rather not, and the match reads them: a corner goes to that flag's man while he is on the pitch, about 8 of your goals in a hundred come from the spot and 4 from a direct free kick, both credited to the taker, a save can be a saved penalty, the penalty taker's rating shifts a shootout a touch, and the eleven lose one morale point less to a defeat with the captain out there. Sell or loan a man out and every job naming him is cleared, so nothing travels. Set a shootout order on the same tab and penalties go kick by kick instead: your men step up in the order you picked (anyone subbed off or sent off is skipped, anyone you left out follows in the order of your eleven with the keeper last), each kick's odds move a touch with the taker and the keeper facing him (where the old one draw, still what you get with nobody listed, leans toward the stronger side), and the report lists every kick.</p>
              <p>🏋️ <span className="font-semibold text-foreground">Training is two switches and a second position.</span> How hard you work them and who the week is built around are set on the Training tile, and the same tile retrains an outfielder into a second position: about 6 weeks for a position next to one he holds, 10 for another on the same line, 16 across lines, half as long again past thirty, shorter with a better training ground and never under 4. One man learns one position at a time, keeps two at most (the oldest makes way for a third), and keepers stay keepers, nobody else goes in goal. When it lands the position is his: no fit penalty in that slot, the auto pick and the bench read it as his own, and it shows as a small chip beside his position. A real footballer starts with the one position the data gives him, so every second position in your squad was earned in this save.</p>
              <p>📊 <span className="font-semibold text-foreground">One match, two ways through it.</span> Play Live puts both elevens on the pitch, at 0.5x to 4x speed, each man wearing his surname (van Dijk, De Bruyne), or his initials when players bunch up at a wall or a corner, and a side the game has no names for showing each man's position instead (CB, ST). No roster the game holds carries real shirt numbers, so the pitch shows none. The ball sits at a player's feet and passes between them, and the chances, saves, corners, throw ins and fouls land at their real minutes, with goals, cards and subs on both sides, and your injuries. A goal from the spot is marked (P) wherever a scorer is listed. Now and then a goal is an own goal, marked (O.G) under the club that got it: the man named put it into his own net, nobody gets it on his season, and the score is the one the match already had. Under the pitch the live stats count up as it goes: possession, shots and shots on target, expected goals, corners and fouls for both clubs, and at the whistle they are exactly the report's numbers, because the report is counted off the same list. You can pause at any minute, tap one of your players and bring somebody on or change the shape (three changes a match, and the other dugout makes its own), and the rest of the half is redrawn off the change. The break is still the dressing room, where the subs, the shape and the team talk are yours. Quick Sim goes straight to the report with the coach looking after your subs: he replaces an injured player when the bench allows it, and at the break he can take off up to two tired ones. After the break he looks at his bench twice more, around the hour and in the run in: a booked man or the most tired legs come off for a fresher player who plays there, as long as the eleven is no weaker for it, or whatever it costs once you are two goals clear. He always keeps one change back for an injury, and the full time report lists every change he made. Both ways kick off through the same engine, so there is no penalty for skipping, but his changes can move the result the same way yours can. A Champions League final that is level after 90, or a second leg that leaves the tie level on aggregate, plays thirty minutes of extra time before penalties, with the clock running on to 120 and your changes still open. In the eras that had the away goals rule they come first: a tie level on aggregate but not on away goals is over at 90, and an away goal in extra time still counts, so the home side then needs two. Your domestic cup still goes straight to penalties, because the real cups do not all play extra time. The board is real time too: the clock runs on to 45+2' or 90+5' and goals, cards and injuries can land in it, and on the second leg of a two legged tie the first leg and the running aggregate sit under the score so you always know what the tie says, not just the night. The report gives you the scoreline with the stoppage time both halves ran to, scorers, cards and subs on both sides, your injuries, possession as the two shares of the ball, shots, expected goals, a momentum graph drawn from who had the chances in each ten minutes, and every player's rating on both sides. The Match Centre shows both clubs' form, your past meetings and the engine's own win odds before you commit. Every match screen names the home side first, the way a scoreboard does: the next match card, the Match Centre, the live score, half time and the report all read home against away, with each club's stats, scorers and timeline under its own name, so away from home your club sits on the right, picked out in green.</p>
              <p>📈 <span className="font-semibold text-foreground">The stats centre keeps the season's numbers.</span> The club's record split by league, cup, super cups and Europe, the top scorer, the assist king, the best average rating and the most carded man, plus every player's full line (apps, goals, assists, cards, average rating), sortable by any column and filterable by competition. Above it all sit the league leaders: tap Top scorers, Assists or Clean sheets for your league's top ten, where another club's goals are shared out among its men by position and rating, the same way your own squad's goals are (own goals, and goals from places a thin squad's data does not cover, count for nobody), with a ? on the card that shows how. Under them run the award races: a player of the season watch scored by one formula for everyone and the Ballon d'Or conversation, all settled with the season and named in your season review. The Top scorers board is the golden boot, and the review names its winner with the league's most assists, the keeper with the most clean sheets and a team of the season, and Past winners on the stats screen keeps every season's winners, and the team of the season for the last five. In a season the book cannot settle (it started late, or too few of the league's goals have a name on them) the golden boot goes to the older scorers' race instead, shown with the award races, and there is no most assists, most clean sheets or team of the season that year (in a league where the data on most squads is thin, that can be every year).</p>
              <p>🤝 <span className="font-semibold text-foreground">Tell every player what he is</span>: star man, key first teamer, rotation option, backup or one for the future. Each rung is a promise about minutes, and the dressing room keeps score over your last ten matches. A start counts as a game and coming on counts for the minutes he got, so ten minutes at the end does not keep a star man quiet. Keep your word and they play for you. Break it and they sulk, drag the room down and hand in transfer requests. You can buy your way out of a promise, but it costs six weeks of his wages a rung.</p>
              <p>🎙️ <span className="font-semibold text-foreground">Front up to the press, and talk to your players.</span> The reporters only turn up when something has happened: a losing run, a man you have stopped picking, a club circling one of your stars, a derby, or the bookmakers making you favourite for the sack. Every answer spends one thing to buy another, so backing your players costs you with the board and calling them out costs you the dressing room, and talking big before a derby puts your words on the other lot's wall. Before every match and again at half time you pick a tone: calm them, fire them up, demand more, or the hairdryer. Read the afternoon right and they play above themselves. Read it wrong and you lose them, and the wrong one hurts more than the right one helps.</p>
              <p>💰 <span className="font-semibold text-foreground">Buy and sell in the summer and January windows.</span> Over 5,000 real players are on the market at their real values, each one wearing his real nationality's flag, and the deep filters go all the way down: position group or exact position, age, price, selling league, nationality (around 130 real nations, drawn from your world's own market) and four sorts. Stay under budget and keep at least 14 players.</p>
              <p data-cm-help="world-memory">🧭 <span className="font-semibold text-foreground">The world remembers your deals.</span> In a career started from this update on, every player you buy, sell or release, and every one who retires, stays where he went when you change jobs. Say you sell your striker to a rival in the summer and take a job abroad in January: when you look at that rival a season later he is still there, a year older, not back at your old club, and a man you released is still a free agent rather than back where he started. From your second season the rest of the world grows with some variety too: now and then a young player breaks out and a few have setbacks, and every career gets its own version. A career you already had going before this update, or a Hot Seat job you carried on with here, joins in at its next summer: from then on the deals you make stay where they went too. It keeps its own world otherwise, without the extra variety, with one small change from that summer: a player rated over 95 is no longer cut back to 95 each summer.</p>
              <p>📝 <span className="font-semibold text-foreground">Every player is on a real deal.</span> Wages sit on a curve, and the board sets a weekly ceiling taken off the squad they handed you on day one. It moves with the club's season after that, up a bit when you beat what they asked for and further for a trophy, back down after a bad one, and it never moves with your own wage bill, so signing big does not talk them into paying for it. Contracts tick down: a man you never sit down with walks for free in the summer, with his sale value already collapsed. The contracts desk on the Squad tab re-signs anyone in his final year, two ways: the full-wage deal, or 12 percent cheaper with a release clause written in at 1.5 times his value that day. The clause is a real exit door. Any club can pay it, it cannot be rejected or blocked, an unanswered one executes itself on deadline day, and the only way to delete it is a full price renewal later. Grow a star past his own clause and the phone will ring.</p>
              <p>🚪 <span className="font-semibold text-foreground">You can end a deal early, but it costs.</span> The contracts desk has a Release button beside every senior player, and it asks twice before it does anything. Let a man go and you keep paying half his wage every week until his deal would have run out, capped at two seasons, and that settlement counts against the wage ceiling the whole time, so sacking your worst contracts frees about half their wages, not all of them. The whole dressing room takes a morale hit, a bigger one for a player they rated, and a man you release never signs for you again. Nobody can be released mid match, and neither can your only keeper, a man who is part of a deal on the table, or anyone who would leave you under 14 players or under 12 senior ones.</p>
              <p>🆓 <span className="font-semibold text-foreground">Free agents sign any time, window or no window.</span> The list on the contracts desk starts every season with six journeymen without a club, all made up and marked MADE UP, plus players whose deals ran out with you once a season has gone by since they walked. A brand new career in today's world also opens with a few real players who had no club when we checked them against two sources. They join the list on day one and never again. The list is cover, not an upgrade: a free agent only signs if he sits at least 6 points below your club's level, and a man who never played for you also has to be no better than your eleventh best player, so the good ones say no. There is no transfer fee, but he wants a wage, a contract length and a signing on fee worked out like a renewal's and never under half a million (a real player never under his market value), all three shown on the Sign button, and the wage has to fit under your ceiling. The journeymen are cover, not an investment: clubs offer next to nothing for one. Anyone left unsigned loses a point every summer and is gone after two.</p>
              <p data-cm-help="game-deals">🧾 <span className="font-semibold text-foreground">A real player's deal is this game's.</span> The game holds nobody's real contract, so the wage and years left on a real player's deal are its own numbers, and the contracts desk, the squad list and the dressing room say so beside them. Made up players, youth players and your academy kids are the game's anyway. Example: say your left back shows this game's deal, 44k a week, final year. That does not mean the real one is out of contract. Renew him at 51k for four years and that is the deal you signed in this career.</p>
              <p>🤝 <span className="font-semibold text-foreground">Sponsors pay the other half of the bills.</span> The Finances desk puts four shirt sponsor offers on the table whenever the club has no deal. Three are honest brands in three shapes: the most guaranteed money, less money with a real bonus for winning the league, or the smallest cheque locked in for four seasons with a little for a top half finish, each marked local or global. The fourth is a bad brand (a bookmaker, a lender, that sort) paying 1.35 times the safe cheque: the fans lose 6 mood the day you sign and 8 off their target every week it runs, and the board like the money by a point. Every offer takes a push: ask for more and the brand comes up six percent, ask once too often and it walks for the season. The money lands in the same kitty as everything else, once a season, and the bonus lands at the season end that earns it. Leave the club and the deal stays behind, because it was the club's and not yours.</p>
              <p>🎟️ <span className="font-semibold text-foreground">The club earns while you manage, and the fans have a say.</span> Every home crowd pays the transfer kitty: attendance times the money a head, which is your ticket price plus food and drink at your prices. Fair tickets and cheap food lift the fans' mood, premium anything costs it, and the mood moves your home crowd, 0.9 times when they are furious and 1.1 when they are singing; the board go the other way, a point of confidence for premium tickets and a point off for fair ones. The Finances desk also projects the season's books to the last day: tickets, food, the sponsor and deals in, player wages, staff wages, travel, deals and the builders out. Wages and travel are running costs the board covers, so they never leave the kitty; the wage ceiling on the contracts desk is how the board keeps them honest. It is all one kitty otherwise: gates in, transfers, scouts, the academy and the facilities out. Whatever you did not spend rolls into the summer on top of the board's new cheque, up to one more season's worth. Leave the club and the balance stays behind, the same as the sponsor deal and the facilities, because it was always the club's money.</p>
              <p>🏗️ <span className="font-semibold text-foreground">Four facilities, level 1 to 10.</span> Stadium, training ground, medical and dressing room, on the Facilities desk. A club opens where its stature puts it: the giants on 8 to 10, most clubs on 1 or 2. Every level is a lift on the game you already play and level 1 does nothing at all: the training ground speeds growth for anyone with room under his ceiling (nobody grows past it), medical writes injuries for fewer weeks (never under one), the dressing room brings unhappy players back toward content between games, and the stadium lifts the food and drink money a head, with the first three levels you buy also growing the crowd. Upgrades come out of the transfer kitty and get dearer every level, so a small club cannot build a level 10 anything in a season.</p>
              <p>🧑‍🏫 <span className="font-semibold text-foreground">Four people on the staff, and rivals want them.</span> An attack coach, a defence coach, a goalkeeping coach and a lead scout, all made up, each with a level 1 to 10 and a ceiling he can still reach. A club opens where its stature puts it, the same as the facilities. Each one is a lift and level 1 does nothing at all, so an empty chair costs you nothing you already had: the attack coach speeds up the forwards and the number ten, the defence coach the back line and the holding midfielder, the keepers get their own man, and the middle of the park splits the two coaches between them. Nobody grows past his ceiling whoever is coaching him. The lead scout is the one who reads the trip reports, so the boys your scouts come home with have a little more in them. Their wages are a running cost the board covers; hiring costs a fee and paying somebody off costs severance, and both come out of the kitty and show up on the Finances desk. You can also promote from your own academy staff for nothing: he starts lower than anyone on the shortlist and has the furthest to grow, and how good he is comes off your academy's coaching level. Rival clubs come in for the good ones on their own schedule, and you get {STAFF_MATCHES_PER_SEASON} matches a season: match the money and he stays on a quarter more wages, or let him go and the job opens. Ignore an approach for two weeks and he leaves anyway. The staff belong to the club, so a new job starts on the new club's people.</p>
              <p>🌐 <span className="font-semibold text-foreground">Win enough and your country calls.</span> A national federation can offer you the international job alongside your club. Club football does not change at all: the country plays between seasons, in the real tournaments, with the real qualifying groups and the slot counts each confederation actually gets. A good manager makes his country more likely to win one, but the players still decide most of it. Win a tournament and it goes in the same cabinet as a league title. Miss one your country should have reached and the federation moves on.</p>
              <p>🧳 <span className="font-semibold text-foreground">And if they do sack you, that is not the end.</span> You go out of work with your record intact and clubs start calling: real clubs from the real pyramid, with the job they are actually offering written out. Trophies and title finishes open doors, relegations shut them. Every week you wait for a better job cools the market a little, and somebody always takes a chance on you in the end. Take one and you start next season there.</p>
              <p>👥 <span className="font-semibold text-foreground">Three managers, three careers, one device.</span> Tap Managers at the top of the hub, or Your managers at the end of a season, to see your three slots. Each one holds a whole career of its own: Resume Career picks it up where you left it, New manager starts another in an empty slot without touching the others, and Delete asks before it wipes one for good. Start a new manager at the end of a season, or start again after the sack, and that career keeps its slot and starts the new one in an empty slot; with all three full you delete one first. Example: slot 1 is your Everton career in its fourth season with two cups in the cabinet. You tap Managers, pick New manager in slot 2 and take 2010-11 Barcelona. Everton waits where you left it, cups, board and all, and next time you open the game both tiles are there.</p>
              <p>📉 <span className="font-semibold text-foreground">Two meters sit under the club name on every tab: the board and the fans.</span> Tap either one to swap its words for the number out of 100. The board meter is the sack race itself, nothing prettier: it opens at {BOARD_FRESH} in any new job and anywhere from 35 to 82 after a season you stayed for, depending on how that season went (the last block below has the sum), a win adds about 4, a defeat takes about 4.5 (more at a giant, more again when the papers have turned on you), the table against what the club expects moves it a little every league week, a cup exit or a promise to the press you broke costs extra, and at zero you are sacked. Safe is 60 and above. Under pressure is 10 to 59. Under 10 it reads One bad week from the sack, and it means it: a single week has been measured taking more than 10 off, because a defeat, the table, a cup exit and a promise to the press broken can all land in the same seven days. Between matches nothing can sack you: a press answer, a handshake with another club or a switch on the Finances desk can drain the board to its last point, and the next result decides. The fan meter is read off what fans actually feel: this season's results weighted towards the recent ones (the biggest term, worth 34 points either way), your league position against the club's own expectation (2.5 a place, capped at 15), the ticket policy on the Finances desk (fair prices +4, premium -5), what a pie costs in the ground (cheap +3, premium -4), a shirt sponsor they are ashamed of (-6) and every trophy lifted this season (+8 each, up to 16), all on top of a base of 55. Singing is 65 and above, Grumbling is 40 to 64, Turning is under 40, and Hopeful is what they are before a ball is kicked. Overachieve and bigger clubs come calling, from any league in the game, and some of them call MID-SEASON: an approach lands in the Manager panel, and committing to it is a summer pre-agreement your current board will hear about on the radio. They can even walk away again if your season collapses after the handshake. And you can go the other way: apply for a job yourself from the Manager panel, any club in any league, wait a few match days for an answer, and if they say yes you join right then (the season there so far is simulated, like a takeover) or at the start of next season. One application at a time, three a season, none in the last five league games or while an approach is waiting on you, and a club that turns you down will not take another call until next season is over.</p>
              <p>🏆 <span className="font-semibold text-foreground">Season score, out of 130, and it is about you rather than about the club you picked.</span> Five things count. League form is worth up to 48, and it is your share of the points your own fixture list offered, so a 46 game season and an 18 game one are scored the same way and a small league is not worth less than a big one. Winning your league is 28 wherever you win it. A domestic cup run is worth up to 24 (5 for the quarter finals, 11 for the semis, 17 for the final, 24 for lifting it) and a European run up to 24 (7 for reaching the knockouts, 13 for the semis, 18 for the final, 24 for winning it). And every board objective you tick is 6, up to 30, settled at the final whistle the same way the board settles the card itself. Those five add up to 154 between them, so the scale stops at 130 before they do: you do not have to win literally everything to top it out, and a league with no European route can still reach 130 through the league, the cup and the board. Take over a club part way through a season and the manager before you keeps his share: you are scored on the games you actually picked a team for. The season end screen lists what each part paid. Careers span multiple seasons; your save is kept on this device.</p>
              {/* Round 1302 fix: this was one paragraph of about forty lines, taller than a phone screen (960 px at
                  390 wide). The same sentences, in short paragraphs, with the list of competitions on its own. */}
              {CM_VAR_LIVE && (VAR_GOALS || VAR_PENALTIES) && <div data-cm-help="var" data-cm-help-kinds={CM_VAR_KINDS.join(' ')} className="space-y-2">
                <p>📺 <span className="font-semibold text-foreground">VAR in today's game.</span> In a save that starts in 2026/27, a match can go to a video review from its next kickoff, but only in the competitions we have checked really use VAR this season.</p>
                <p data-cm-help="var-list"><span className="font-semibold text-foreground">Right now that is:</span> {CM_VAR_COVERED_NAMES.join(', ')}. A cup on that list has it from the round of 16 on unless the list says otherwise.</p>
                <p><span className="font-semibold text-foreground">Everything else plays without it,</span> either because the real competition does not use it this season or because we could not confirm on two sources that it does, and the older eras (the 2005, 2010, 2015 and 2020 starts) never get it, even when they run on past 2026.</p>
                <p><span className="font-semibold text-foreground">What gets reviewed.</span> In real football a review can look at goals, penalty calls, red cards (since July 2026 that includes one that came from a clearly wrong second yellow) and a card shown to the wrong player, and the referee's call stands unless it was a clear and obvious error. {VAR_GOALS && VAR_PENALTIES ? 'This game reviews goals and penalties only.' : VAR_PENALTIES ? 'This game reviews penalty calls only.' : 'This game reviews goals only: a review can rule a goal out, and it looks at nothing else.'}</p>
                <p><span className="font-semibold text-foreground">In Play Live</span>{VAR_GOALS ? ' a goal that gets ruled out goes in first and the check comes after. Then it counts for nothing: no score, no scorer, no shot on the stats.' : ''}{VAR_PENALTIES ? ' A foul the referee missed can become a penalty, and the kick is a real one that can go in, be saved or miss.' : ''} You only see a review that changed the call, and it is rare.</p>
                <p><span className="font-semibold text-foreground">How often.</span> Rarely, and on purpose. We read the published season counts we could find, kept only what more than one publisher counts, and set the game at the cautious end of them, so a review changes fewer results, not more. In this game that is{VAR_GOALS ? ` a goal ruled out about once in ${Math.round(1 / CM_VAR_REAL.goalsRuledOut.low)} matches` : ''}{VAR_GOALS && VAR_PENALTIES ? ' and' : ''}{VAR_PENALTIES ? ` a penalty given about once in ${Math.round(1 / CM_VAR_REAL.penaltiesAwarded.low)}` : ''}. It works both ways, for you and against you, and it does change results.</p>
                <p><span className="font-semibold text-foreground">Example:</span> {VAR_GOALS && VAR_PENALTIES ? 'it is 0-0, a goal is ruled out, then a penalty a review gave is missed. It stays 0-0.' : VAR_PENALTIES ? 'it is 0-0 and a penalty a review gave is missed. It stays 0-0.' : 'it is 0-0, the ball goes in, a check opens and the goal is ruled out. It stays 0-0, with no scorer and no shot on the stats.'} Each decision is made once and saved with the match, so the live match and the full time report always agree. Open the match's ? button to read this again.</p>
              </div>}
              {/* Round 1323: one tab wins (src/lib/saveFence.ts). Appended on its own. */}
              <div data-cm-help="one-tab" className="space-y-2">
                <p>🗂️ <span className="font-semibold text-foreground">One tab at a time.</span> Each career has one save, so if Club Manager is open in two tabs, the newest tab is the one that plays. The older tab stops saving and puts up a notice asking you to reload, so it can never write an old week over what you played in the other one, or play a match again that is already done. Reloading a tab makes it the newest.</p>
                <p><span className="font-semibold text-foreground">Example:</span> you are on week 5 in one tab, open Club Manager again in a second tab and play three matches there. Go back to the first tab and it says the career moved on in another tab. Tap Reload and your managers screen comes back with the career at the second tab's week, all three results in. Tap Resume Career and carry on from there.</p>
              </div>
              {/* Round 1331: the substitution rule by league and season (src/lib/clubManagerSubsRule.ts). Appended on its own. */}
              <div data-cm-help="subs" className="space-y-2">
                <p>🔁 <span className="font-semibold text-foreground">Substitutions.</span> How many changes you get depends on the league and the season, the way it really was. Up to 2019-20 it is three, whenever you like. Spain, Italy, Germany and France went to five from 2020-21, and the Premier League and the Championship for good from 2022-23. Five comes with a catch: you only get three stoppages in play to make them. A change at half time or just before extra time does not use one, and two changes at the same minute use one between them. Wherever this guide says three changes, it means a three change match.</p>
                <p><span className="font-semibold text-foreground">Example:</span> a 2026-27 Premier League match. Two changes at half time cost no stoppage. Then one at 60, one at 70 and one at 80, and that is all five changes and all three stoppages gone. A 2005-06 match gives you three, whenever you like.</p>
                <p>The other dugout and the Quick Sim coach play the same rule, and under five the coach keeps a stoppage back for an injury as well as a change. Cups and European ties play your league's rule. The 2019-20 restart did allow five, but a season here goes by the year it starts, so 2019-20 plays three. Every other league in the game (the Eredivisie, MLS, the Saudi Pro League and the rest) keeps three for now, because we could not confirm its rule on two sources yet.</p>
              </div>
              {/* Round 1335: the board's verdict, the openings, the offers and the kitty (src/lib/clubManagerBoardVerdict.ts). Appended on its own. */}
              <div data-cm-help="board-verdict" className="space-y-2">
                <p>🧾 <span className="font-semibold text-foreground">The board's verdict and your next job.</span> The grade reads your season against what the club expected. In a league where the game moves clubs up and down, going up is at least a B and the review says so, going down is at most a C (a B if you won a trophy), and staying up when the board had you going down gets its own line. The statues are for titles and doubles only.</p>
                <p>Next season opens from 55: plus 1.5 for every place above where the club you played for was expected to finish (minus 1.5 for every place below), plus 2 for every objective you hit and minus 2 for every one you missed. The season's main demand (the title, a top four, promotion, staying up) counts three times, and each of the board's five specific asks counts half. Every promise to the board you kept or broke is worth 3 either way. Then a season graded A or B opens at {BOARD_FRESH} at least, a D or an F opens under 60, and nothing opens under 35 or over 82. Every new job opens at {BOARD_FRESH}: your first, a summer move, a mid season takeover and an application that said yes. So one bad night usually still leaves you Safe, though a cup exit on top of the defeat can take you under.</p>
                <p>Clubs that call you at the end of a season are one tier above yours at most, or two after a top flight league title or a Champions League win, and a chair that empties at a club your size abroad can still call. A mid season approach comes from one tier up too. A club you applied to yourself, or shook hands with during the season, is your call and still stands. That is the game's rule, not a claim about how real managers move. Tap an offer to see it first: nothing moves until you take the job.</p>
                <p>Take over in mid season and the card starts with what is still open: anything the last manager had already failed is off it. And the board's summer cheque grows with a good season but never past {KITTY_TOP_SHARE} times the club's usual budget (or 10m). Money you did not spend still carries, up to one more cheque.</p>
                <p><span className="font-semibold text-foreground">Example:</span> a club expected to finish 1st wins the league and hits its cup target, but misses its goals target and two of the board's asks. That is 55 + 1.5 x 0 + 2 x (3 + 1 - 1 - 0.5 - 0.5) = 59, but it is an A season, so next season opens at {BOARD_FRESH}, Safe. Before this the same season opened at 55 + 2 x (1 + 1 - 1 - 1 - 1) = 53, Under pressure. And a club that goes up in 2nd in the Championship gets at least a B and a line saying it is up to the Premier League.</p>
              </div>
              {/* Round 1342: No sacking (src/lib/clubManagerStart.ts). Appended on its own; the board sentences above
                  stay true for every career without it, and the first line here says which one they leave out. */}
              <div data-cm-help="no-sacking" className="space-y-2">
                <p>🛡️ <span className="font-semibold text-foreground">No sacking.</span> Everything above about the sack is for a normal career. Switch on No sacking and zero is no longer the sack for you: the board still moves after every match and still tells you what it thinks, but where it would fire you it keeps you on its last point instead. Pick it on the Dugout step when you start, or turn it on later from Options (it asks twice). It cannot be turned off, it cannot be turned on while you are out of work, and from then on the career posts no score to the leaderboards, though your days played still count. Manager Hot Seat and Deadline Day never use it.</p>
                <p>It also takes some of the bite out of the wage ceiling. Going over the ceiling still costs board confidence after every match and still stops free agents signing, but with No sacking on the lost confidence can no longer cost you the job.</p>
                <p><span className="font-semibold text-foreground">Example:</span> the board is on 2 and you lose 3-0 in the league. On a normal career that is almost always the sack. With No sacking the board stays on 1, the match report says they would have sacked you, and you play the next match.</p>
              </div>
              {/* Round 1343: retiring, and the highest scoring game (src/lib/clubManagerRetire.ts, clubManagerRecords.ts). Appended on its own. */}
              <div data-cm-help="retire" className="space-y-2">
                <p>👋 <span className="font-semibold text-foreground">Retiring.</span> You can retire whenever you are between matches: from the Manager panel, from the season summary, or while you are out of work. One tap asks first and says what it means, and a second tap retires. It ends the career for good. Nothing more gets played, and if you go in the middle of a season that season stays unfinished. Once the last match of a season is played, the door waits until you have opened See Season Review, so that season counts, title and all. The career keeps its slot as a finished one, with a farewell you can open from your managers screen any time. A new manager starts in an empty slot.</p>
                <p><span className="font-semibold text-foreground">Highest scoring game</span> on your record is the match with the most goals in it, both sides together, extra time included and penalty shootout kicks never. Every club match on your record counts, the same ones your wins, draws and losses count. If two games tie, the first one stays.</p>
                <p><span className="font-semibold text-foreground">Example:</span> a 4-4 draw in Season 2 and a 5-3 win in Season 4 both have eight goals, so your record keeps the 4-4. A 3-3 cup tie you won on penalties counts six.</p>
                <p><span className="font-semibold text-foreground">Example:</span> a career saved before this line was added works it out from the scores the save still keeps. If it no longer keeps all of them, the line says how many of your matches it could not see.</p>
              </div>
              {/* Round 1344: a deal between two other clubs reaches the world ledger (generateHeadlines in
                  src/lib/clubManager.ts). Appended on its own; it points back to the world memory paragraph. */}
              <div data-cm-help="world-moves" className="space-y-2">
                <p>🔄 <span className="font-semibold text-foreground">Deals between other clubs stick too.</span> The world remembers your deals (see above), and it remembers the other clubs' deals as well: straight away in a career started after the 13 October update, and from its next summer in a career started before it or a Hot Seat job you carried on with here. When the news says a club signed a player, he is in their squad straight away: on their club page, in their line ups against you, and on the transfer market at his new club. They will not sell him on until the summer, and the market tells you so if you try. A player you sell works the same way.</p>
                <p><span className="font-semibold text-foreground">Example:</span> Napoli sell a winger to Arsenal in the summer news. He is in Arsenal's squad on their club page straight away, he can play against you for Arsenal, and the market lists him at Arsenal, not for sale until next summer. A season later he is still there, a year older.</p>
                <p>Club strengths and the golden boot race are worked out once a season, so a window's moves count there from the next season. If your career is newer than that update and a move this season went missing, opening it puts him where he went; moves from earlier seasons stay where they were. A career started before the update joins in at its next summer, and the deals from before that summer stay as they were.</p>
              </div>
              {/* Round 1501: how hard (src/lib/clubManagerDifficulty.ts). Appended on its own. Its first sentence says
                  everything else on this screen, numbers and promises alike, is Medium's (Round 1512: five levels, changeable in
                  Options), so none of it turns false on another level (the board verdict block's "one bad night usually still leaves you Safe" is not true at a big
                  club on Hard, and the detail paragraph says so; Round 1512 closing check: one short line per level, then that
                  detail); the example's numbers are the dial table's, and
                  scripts/simCmDifficulty.mjs section 7 holds them to it. */}
              <div data-cm-help="difficulty" className="space-y-2">
                <p>🎚️ <span className="font-semibold text-foreground">How hard.</span> Everything elsewhere on this screen, every number and every promise, is for a Medium career, and No sacking (above) switches off the zero rule whatever the level. You pick a level on the Dugout step when you start, and you can change it any time between matches in Options, or on the sacked screen while you are out of work: it counts from your next match and the money from your next cheque or new job, the market's prices to you change straight away, and nothing you have already played changes. There are five:</p>
                <ul className="list-disc pl-5 space-y-1">
                  <li><span className="font-semibold text-foreground">Very Easy:</span> the kindest board, the most money and wage room, the cheapest signings, and every opponent a few points below itself against you.</li>
                  <li><span className="font-semibold text-foreground">Easy:</span> a kinder board, more money and wage room, cheaper signings, and every opponent a little below itself against you.</li>
                  <li><span className="font-semibold text-foreground">Medium:</span> the game as it has always played.</li>
                  <li><span className="font-semibold text-foreground">Hard:</span> a stricter board, less money and wage room, dearer signings, and every opponent a little above itself against you.</li>
                  <li><span className="font-semibold text-foreground">Impossible:</span> the strictest board, the least money and wage room, the dearest signings, and every opponent a few points above itself against you.</li>
                </ul>
                <p>In more detail. On Easy and Very Easy the board gives you more for a win and takes less for a defeat, its money is bigger, a new job starts with more room on wages, and the market lists men to you below their list, never under 0.5m and never under what selling the man straight back would bring (so a man of 30 or over costs his full list); a bad season still opens the next one where it would on Medium. On Hard and Impossible the board gives you less for a win and takes more for a defeat, so in a new job at an Elite or Contenders club, or a Challengers one on Impossible, one bad night can already take you under Safe; a season that would open the next one under Safe opens it lower still (a season it liked still opens Safe); the board's money is smaller, on day one, every summer and when you move; a new job starts with a tighter wage ceiling; and the market lists every man to you at a higher price than his list, and his release clause is never cheaper than that.</p>
                <p>The edge, up or down, is in every match of yours, cups, Europe and finals too, and never in a match between two other clubs. A penalty shootout feels it only until you name your penalty order: after that the kicks use the men's own ratings, apart from the made up takers a thin side needs, who kick at the club's strength with the edge added. The other side's players keep their ratings on screen. The summer's international tournaments are played on their own rules and never see it. The clubs you deal with charge you more on Hard and Impossible and less on Easy and Very Easy (a release clause there costs what it does on Medium), but the money the other clubs pay each other is unchanged, and a loan (still two at a time, for the same young or fringe men) is priced as it always was. Negotiation strictness in Options is a separate setting and works the same at every level. Manager Hot Seat and Deadline Day always play Medium. Medium, Hard and Impossible careers post to the leaderboards as they always did. A career that is ever on Easy or Very Easy posts no leaderboard scores from that moment on, even if you move it back up.</p>
                <p><span className="font-semibold text-foreground">Example:</span> at a Challengers club sitting where it was expected to, with the press neutral, a league defeat costs the board 4.5 on Medium, 5.6 on Hard and 6.7 on Impossible, but 3.6 on Easy and 2.7 on Very Easy, and a win gives back 4, 3.2, 2.6, 4.8 and 5.6 in the same order. A 40m summer cheque is 32m on Hard, 26m on Impossible, 48m on Easy and 60m on Very Easy. A man of 23 or under listed at 10m costs you 11.5m, 13m, 8.7m and 8m. An opponent of 80 plays you at 81.5, 83, 78.5 and 77. And a bad season that would open the next at 35 opens it at 27 on Hard and 21 on Impossible, and still at 35 on Easy and Very Easy.</p>
              </div>
              {/* Round 1503: the Champions League in it or not (src/components/club-manager/WorldCompScreen.tsx). Appended
                  on its own. The example's clubs and dates are the game's own, read off a 2026-27 Chelsea save and a
                  2005-06 Sunderland save on the engine, never the real season's. */}
              <div data-cm-help="world-ucl" className="space-y-2">
                <p>🌍 <span className="font-semibold text-foreground">The Champions League, in it or not.</span> Every season the whole Champions League plays out in your world, whether or not your club is in it. Open Cups, then Champions League: Table (Groups in the old seasons), Matchdays, Knockouts and Final. Tap any club to see its run: every game with its date and score, and where it finished or went out. A night shows only once your season has passed it, and the dates are your own calendar's, so they are the game's, not the real season's. In today's world the competition you follow from outside is the real format, 36 clubs in one table; your own club, when it qualifies, still plays the game's stand in, eight groups of four into the quarter-finals. The old seasons play eight groups of four into a round of 16 for the whole life of the save, from the same real 32 clubs every season, except that your own club can change one place (in it from outside the 32, or one of them and not in it), and the screen names that place. The draw is the game's own: pots by how strong the clubs are in your save, the holders first.</p>
                <p><span className="font-semibold text-foreground">Example:</span> start 2026-27 at Chelsea. The game has them outside the places, so you are not in it. Cups, then Champions League: 36 clubs in one table, with eight matchdays on your calendar from late August to January. 1st to 8th go straight to the round of 16, 9th to 24th play a two legged play-off in February, and 25th and below are out. The final comes after your last league game, and its winner is in next season's draw whatever its league did.</p>
                <p><span className="font-semibold text-foreground">Example:</span> start 2005-06 at Sunderland, not in it either. Eight groups of four, everyone playing home and away, and the top two of each group go into a round of 16 drawn winner against runner-up, never from the same group or country. Every tie before the final is two legs, and away goals count when the aggregate is level.</p>
              </div>
              {/* Round 1509: the Europa League, followed every season of today's world (WorldCompScreen.tsx by key).
                  Appended on its own. The example is the engine's own season one field for a Chelsea career,
                  printed by scripts/simWorldEuro.mjs section 7, read off the real 2025-26 tables by the rule. */}
              <div data-cm-help="world-uel" className="space-y-2">
                <p>🌍 <span className="font-semibold text-foreground">The Europa League.</span> In today's world the whole Europa League plays out every season too: 36 clubs in one table on Thursday nights, then the knockouts and the final. Open Cups, then Europa League, for the table, the matchdays, the knockouts and the final, and tap a club for its run and how it got in. Who is in it: in each league, the club just below its Champions League places, and your own country's cup winner. A club already in the Champions League, or a cup winner already in, hands its place down the table. Cups abroad are not played in the game, so from your second season their place goes down their league. The last places go to the next best placed clubs of the strongest leagues, and the winner goes into next season's Champions League (in a season your own club is in that one, only when the game's smaller field has room). Your own club does not play its Europa League nights yet, so a place it earns goes to the next club in line, and the screen says how you earned it. The board counts the same places: win your cup, or take the place it passes down the table, and Qualify for the Europa League is done, whatever your position. Through the season the board reads your league place and, once it is played, your cup final; a place that only comes down to you once every league has finished counts when the season ends. The old seasons keep their own format and have no Europa League here.</p>
                <p><span className="font-semibold text-foreground">Example:</span> start 2026-27 at Chelsea. The field comes from the real 2025-26 tables. Liverpool finished fifth and are in the Champions League, so the Premier League's place goes to sixth placed Bournemouth. Manchester City won the FA Cup and are in the Champions League too, so the cup's place goes down the table to Sunderland. Crystal Palace are in as the Conference League winners, and Brighton come in on the fill.</p>
              </div>
              {/* Round 1510: the domestic super cup, followed from the Cups panel (WorldCompScreen.tsx's fourth tile).
                  Appended on its own. The example's clubs and ground are the ledger's verified season one edition
                  (scripts/data/cmOneOffFormats.json, eng-2026-s1); its date is the game's own calendar. */}
              <div data-cm-help="super-cup" className="space-y-2">
                <p>🛡️ <span className="font-semibold text-foreground">The super cup.</span> Every season opens with your country's super cup wherever the game can prove its format. In England that is the FA Community Shield: one match on a neutral ground between last season's Premier League champions and the FA Cup winners (the league runners up when the champions won both), and if it is level after 90 minutes it goes straight to penalties. The game plays it on the Wednesday before your first league game, on its own calendar, so the date is the game's and never the real one. Open Cups, then Super cup, for the clubs, why each is in, the date, the ground and the score.</p>
                <p><span className="font-semibold text-foreground">Play it.</span> From your second summer in charge, if your club earned a place (the champions, the cup winners, or the league runners up when one club won both), the super cup is your first match of the season, picked and played like any other, live or quick sim, with your shootout order if it goes to penalties. It is not a week of its own: no wages for it and no window week, and the men who played pay its fitness cost and get a midweek's recovery. Win it and it goes in your cabinet and your record. The board, the sponsor, the fans' trophy count and the job market do not count it, and it pays no prize money (a neutral ground pays no gate either). A red card in it bans the man for your league opener, the game's rule for any red. Its games have their own Super cups view in the stats centre.</p>
                <p><span className="font-semibold text-foreground">Example:</span> start 2026-27 at Chelsea. Arsenal, the 2025-26 Premier League champions, play Manchester City, the FA Cup winners, at the Principality Stadium in Cardiff on Wednesday 5 August, and you follow the result from Cups. Start at Arsenal or Manchester City and your club's place was settled before you arrived: your first super cup is the next one your club earns, from next summer.</p>
                <p>No other country's super cup is in yet, Spain's, Italy's, Germany's and France's among them, and no past season's either: the game has not confirmed them on two sources, so nothing is played there and the tile says Not confirmed. A career saved before this update meets its first super cup next summer.</p>
              </div>
            </div>
  );
}
